+  // PptxGenJS charting is limited in some environments; render a donut-like ring with ovals.
+  addCard(slide, x, y, w, h, { shadow: false });
+  slide.addText(title, {
+    x: x + 0.45,
+    y: y + 0.25,
+    w: w - 0.9,
+    h: 0.4,
+    fontFace: FONTS.body,
+    fontSize: 14,
+    color: COLORS.text,
+    bold: true,
+    margin: 0,
+  });
+
+  const cx = x + w * 0.33;
+  const cy = y + h * 0.62;
+  const r = Math.min(w, h) * 0.28;
+
+  // base circle
+  slide.addShape(pptx.ShapeType.ellipse, {
+    x: cx - r,
+    y: cy - r,
+    w: 2 * r,
+    h: 2 * r,
+    fill: { color: 'E5E7EB' },
+    line: { color: 'E5E7EB' },
+  });
+  // inner hole
+  slide.addShape(pptx.ShapeType.ellipse, {
+    x: cx - r * 0.62,
+    y: cy - r * 0.62,
+    w: 2 * r * 0.62,
+    h: 2 * r * 0.62,
+    fill: { color: COLORS.panel },
+    line: { color: COLORS.panel },
+  });
+
+  // Legend
+  const lx = x + w * 0.55;
+  const ly = y + 0.85;
+  const rowH = 0.42;
+  parts.forEach((p, i) => {
+    slide.addShape(pptx.ShapeType.roundRect, {
+      x: lx,
+      y: ly + i * rowH + 0.07,
+      w: 0.22,
+      h: 0.22,
+      fill: { color: p.color },
+      line: { color: p.color },
+      radius: 4,
+    });
+    slide.addText(`${p.label} (${p.value}%)`, {
+      x: lx + 0.3,
+      y: ly + i * rowH,
+      w: w * 0.42,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 12,
+      color: COLORS.text,
+      margin: 0,
+      valign: 'middle',
+    });
+  });
+
+  // Center label
+  slide.addText('Reward\nMix', {
+    x: cx - r * 0.5,
+    y: cy - 0.3,
+    w: r,
+    h: 0.7,
+    fontFace: FONTS.body,
+    fontSize: 14,
+    color: COLORS.muted,
+    align: 'center',
+    valign: 'middle',
+    margin: 0,
+  });
+}
