+function addStackedBar(slide, x, y, w, h, parts, title) {
+  addCard(slide, x, y, w, h, { shadow: false });
+  slide.addText(title, {
+    x: x + 0.45,
+    y: y + 0.25,
+    w: w - 0.9,
+    h: 0.4,
+    fontFace: FONTS.body,
+    fontSize: 14,
+    color: COLORS.text,
+    bold: true,
+    margin: 0,
+  });
+  const total = parts.reduce((s, p) => s + p.value, 0);
+  const bx = x + 0.6;
+  const by = y + 1.0;
+  const bw = w - 1.2;
+  const bh = 0.55;
+
+  let curX = bx;
+  parts.forEach((p) => {
+    const segW = (p.value / total) * bw;
+    slide.addShape(pptx.ShapeType.rect, {
+      x: curX,
+      y: by,
+      w: segW,
+      h: bh,
+      fill: { color: p.color },
+      line: { color: p.color },
+    });
+    curX += segW;
+  });
+  slide.addShape(pptx.ShapeType.roundRect, {
+    x: bx,
+    y: by,
+    w: bw,
+    h: bh,
+    fill: { color: 'FFFFFF', transparency: 100 },
+    line: { color: COLORS.line, width: 1 },
+    radius: 10,
+  });
+
+  // Legend rows
+  const lx = x + 0.6;
+  const ly = y + 1.75;
+  const rowH = 0.42;
+  parts.forEach((p, i) => {
+    slide.addShape(pptx.ShapeType.roundRect, {
+      x: lx,
+      y: ly + i * rowH + 0.07,
+      w: 0.22,
+      h: 0.22,
+      fill: { color: p.color },
+      line: { color: p.color },
+      radius: 4,
+    });
+    slide.addText(`${p.label}: $${fmtNum(p.value, 2)}B`, {
+      x: lx + 0.3,
+      y: ly + i * rowH,
+      w: w - 1.0,
+      h: rowH,
+      fontFace: FONTS.body,
+      fontSize: 12,
+      color: COLORS.text,
+      margin: 0,
+      valign: 'middle',
+    });
+  });
+
+  slide.addText(`Total: ~$${fmtNum(total, 1)}B`, {
+    x: x + 0.6,
+    y: y + h - 0.55,
+    w: w - 1.2,
+    h: 0.3,
+    fontFace: FONTS.body,
+    fontSize: 12,
+    color: COLORS.muted,
+    margin: 0,
+  });
+}
