+function addSupplyProjectionLine(slide, x, y, w, h, supply0, equilibrium, years, title) {
+  // Use an exponential convergence curve (shape only) without inventing parameters beyond endpoints.
+  // Curve is illustrative; endpoints and equilibrium are sourced.
+  addCard(slide, x, y, w, h, { shadow: false });
+  slide.addText(title, {
+    x: x + 0.45,
+    y: y + 0.25,
+    w: w - 0.9,
+    h: 0.4,
+    fontFace: FONTS.body,
+    fontSize: 14,
+    color: COLORS.text,
+    bold: true,
+    margin: 0,
+  });
+  const padX = 0.6;
+  const padTop = 0.9;
+  const padBottom = 0.75;
+  const cx = x + padX;
+  const cy = y + padTop;
+  const cw = w - 2 * padX;
+  const ch = h - padTop - padBottom;
+  const yMin = supply0;
+  const yMax = equilibrium;
+
+  // axes
+  slide.addShape(pptx.ShapeType.line, { x: cx, y: cy + ch, w: cw, h: 0, line: { color: COLORS.line, width: 1 } });
+  slide.addShape(pptx.ShapeType.line, { x: cx, y: cy, w: 0, h: ch, line: { color: COLORS.line, width: 1 } });
+
+  axisLabel(slide, cx - 0.15, cy - 0.25, 'ETH supply', { w: 2.0 });
+  axisLabel(slide, cx, cy + ch + 0.15, `Years (0 → ${years})`, { w: 3.0 });
+
+  // y labels
+  axisLabel(slide, cx - 0.35, cy + ch - 0.12, `${fmtNum(yMin / 1e6, 1)}M`, { w: 0.9, align: 'right' });
+  axisLabel(slide, cx - 0.35, cy - 0.05, `${fmtNum(yMax / 1e6, 1)}M`, { w: 0.9, align: 'right' });
+
+  // draw curve with simple exponential approach (k fixed to show convergence by ~200 years)
+  const k = 0.02;
+  const pts = [];
+  const steps = 80;
+  for (let i = 0; i <= steps; i++) {
+    const t = (i / steps) * years;
+    const val = equilibrium - (equilibrium - supply0) * Math.exp(-k * t);
+    const px = cx + (t / years) * cw;
+    const py = cy + ch - ((val - yMin) / (yMax - yMin)) * ch;
+    pts.push({ x: px, y: py });
+  }
+  for (let i = 1; i < pts.length; i++) {
+    slide.addShape(pptx.ShapeType.line, {
+      x: pts[i - 1].x,
+      y: pts[i - 1].y,
+      w: pts[i].x - pts[i - 1].x,
+      h: pts[i].y - pts[i - 1].y,
+      line: { color: COLORS.teal, width: 3 },
+    });
+  }
+
+  // equilibrium annotation
+  slide.addShape(pptx.ShapeType.line, {
+    x: cx,
+    y: cy + 0.1,
+    w: cw,
+    h: 0,
+    line: { color: COLORS.teal, width: 1, dash: 'dash' },
+  });
+  slide.addText(`Equilibrium ~${fmtNum(equilibrium / 1e6, 1)}M ETH`, {
+    x: x + w - 3.0,
+    y: cy + 0.1,
+    w: 2.6,
+    h: 0.3,
+    fontFace: FONTS.body,
+    fontSize: 11,
+    color: COLORS.muted,
+    align: 'right',
+    margin: 0,
+  });
+}
