function addDonut(slide, x, y, w, h, parts, title) {
  // PptxGenJS charting is limited in some environments; render a donut-like ring with ovals.
  addCard(slide, x, y, w, h, { shadow: false });
  slide.addText(title, {
    x: x + 0.45,
    y: y + 0.25,
    w: w - 0.9,
    h: 0.4,
    fontFace: FONTS.body,
    fontSize: 14,
    color: COLORS.text,
    bold: true,
    margin: 0,
  });

  const cx = x + w * 0.33;
  const cy = y + h * 0.62;
  const r = Math.min(w, h) * 0.28;

  // base circle
  slide.addShape(slide.ShapeType.ellipse, {
    x: cx - r,
    y: cy - r,
    w: 2 * r,
    h: 2 * r,
    fill: { color: 'E5E7EB' },
    line: { color: 'E5E7EB' },
  });
  // inner hole
  slide.addShape(slide.ShapeType.ellipse, {
    x: cx - r * 0.62,
    y: cy - r * 0.62,
    w: 2 * r * 0.62,
    h: 2 * r * 0.62,
    fill: { color: COLORS.panel },
    line: { color: COLORS.panel },
